    41  // On small screen we hide the search page from central pane to show the search bottom tab page with bottom tab bar.
    42  // We need to take this in consideration when checking if the screen is focused.
    43  const useIsFocused = () => {
    44      const {shouldUseNarrowLayout} = useResponsiveLayout();
    45      const isFocused = useIsFocusedOriginal();
    46      const topmostCentralPane = useNavigationState<RootStackParamList, NavigationPartialRoute<CentralPaneName> | undefined>(getTopmostCentralPaneRoute);
    47      return isFocused || (topmostCentralPane?.name === SCREENS.SEARCH.CENTRAL_PANE && shouldUseNarrowLayout);
    48  };
    49
    50  type PolicySelector = Pick<OnyxTypes.Policy, 'type' | 'role' | 'isPolicyExpenseChatEnabled' | 'pendingAction' | 'avatarURL' | 'name' | 'id' | 'areInvoicesEnabled'>;
    51
    52  type FloatingActionButtonAndPopoverOnyxProps = {
    53      /** The list of policies the user has access to. */
    54      allPolicies: OnyxCollection<PolicySelector>;
    55
    56      /** Whether app is in loading state */
    57      isLoading: OnyxEntry<boolean>;
    58
    59      /** Information on the last taken action to display as Quick Action */
    60      quickAction: OnyxEntry<OnyxTypes.QuickAction>;
    61
    62      /** The report data of the quick action */
    63      quickActionReport: OnyxEntry<OnyxTypes.Report>;
    64
    65      /** The policy data of the quick action */
    66      quickActionPolicy: OnyxEntry<OnyxTypes.Policy>;
    67
    68      /** The current session */
    69      session: OnyxEntry<OnyxTypes.Session>;
    70
    71      /** Personal details of all the users */
    72      personalDetails: OnyxEntry<OnyxTypes.PersonalDetailsList>;
    73
    74      /** Has user seen track expense training interstitial */
    75      hasSeenTrackTraining: OnyxEntry<boolean>;
    76  };
    77
    78  type FloatingActionButtonAndPopoverProps = FloatingActionButtonAndPopoverOnyxProps & {
    79      /* Callback function when the menu is shown */
    80      onShowCreateMenu?: () => void;
    81
    82      /* Callback function before the menu is hidden */
    83      onHideCreateMenu?: () => void;
    84  };
    85
    86  type FloatingActionButtonAndPopoverRef = {
    87      hideCreateMenu: () => void;
    88  };
    89
    90  const policySelector = (policy: OnyxEntry<OnyxTypes.Policy>): PolicySelector =>
    91      (policy && {
    92          type: policy.type,
    93          role: policy.role,
    94          id: policy.id,
    95          isPolicyExpenseChatEnabled: policy.isPolicyExpenseChatEnabled,
    96          pendingAction: policy.pendingAction,
    97          avatarURL: policy.avatarURL,
    98          name: policy.name,
    99          areInvoicesEnabled: policy.areInvoicesEnabled,
   100      }) as PolicySelector;
   101
   102  const getQuickActionIcon = (action: QuickActionName): React.FC<SvgProps> => {
   103      switch (action) {
   104          case CONST.QUICK_ACTIONS.REQUEST_MANUAL:
   105              return Expensicons.MoneyCircle;
   106          case CONST.QUICK_ACTIONS.REQUEST_SCAN:
   107              return Expensicons.Receipt;
   108          case CONST.QUICK_ACTIONS.REQUEST_DISTANCE:
   109              return Expensicons.Car;
   110          case CONST.QUICK_ACTIONS.SPLIT_MANUAL:
   111          case CONST.QUICK_ACTIONS.SPLIT_SCAN:
   112          case CONST.QUICK_ACTIONS.SPLIT_DISTANCE:
   113              return Expensicons.Transfer;
   114          case CONST.QUICK_ACTIONS.SEND_MONEY:
   115              return Expensicons.Send;
   116          case CONST.QUICK_ACTIONS.ASSIGN_TASK:
   117              return Expensicons.Task;
   118          default:
   119              return Expensicons.MoneyCircle;
   120      }
   121  };
   122
   123  const getQuickActionTitle = (action: QuickActionName): TranslationPaths => {
   124      switch (action) {
   125          case CONST.QUICK_ACTIONS.REQUEST_MANUAL:
   126              return 'quickAction.requestMoney';
   127          case CONST.QUICK_ACTIONS.REQUEST_SCAN:
   128              return 'quickAction.scanReceipt';
   129          case CONST.QUICK_ACTIONS.REQUEST_DISTANCE:
   130              return 'quickAction.recordDistance';
   131          case CONST.QUICK_ACTIONS.SPLIT_MANUAL:
   132              return 'quickAction.splitBill';
   133          case CONST.QUICK_ACTIONS.SPLIT_SCAN:
   134              return 'quickAction.splitScan';
   135          case CONST.QUICK_ACTIONS.SPLIT_DISTANCE:
   136              return 'quickAction.splitDistance';
   137          case CONST.QUICK_ACTIONS.TRACK_MANUAL:
   138              return 'quickAction.trackManual';
   139          case CONST.QUICK_ACTIONS.TRACK_SCAN:
   140              return 'quickAction.trackScan';
   141          case CONST.QUICK_ACTIONS.TRACK_DISTANCE:
   142              return 'quickAction.trackDistance';
   143          case CONST.QUICK_ACTIONS.SEND_MONEY:
   144              return 'quickAction.paySomeone';
   145          case CONST.QUICK_ACTIONS.ASSIGN_TASK:
   146              return 'quickAction.assignTask';
   147          default:
   148              return '' as TranslationPaths;
   149      }
   150  };
