   152  /**
   153   * Responsible for rendering the {@link PopoverMenu}, and the accompanying
   154   * FAB that can open or close the menu.
   155   */
   156  function FloatingActionButtonAndPopover(
   157      {
   158          onHideCreateMenu,
   159          onShowCreateMenu,
   160          isLoading = false,
   161          allPolicies,
   162          quickAction,
   163          quickActionReport,
   164          quickActionPolicy,
   165          session,
   166          personalDetails,
   167          hasSeenTrackTraining,
   168      }: FloatingActionButtonAndPopoverProps,
   169      ref: ForwardedRef<FloatingActionButtonAndPopoverRef>,
   170  ) {
   171      const styles = useThemeStyles();
   172      const {translate} = useLocalize();
   173      const [reportNameValuePairs] = useOnyx(`${ONYXKEYS.COLLECTION.REPORT_NAME_VALUE_PAIRS}${quickActionReport?.reportID ?? -1}`);
   174      const [isCreateMenuActive, setIsCreateMenuActive] = useState(false);
   175      const fabRef = useRef<HTMLDivElement>(null);
   176      const {windowHeight} = useWindowDimensions();
   177      const {shouldUseNarrowLayout} = useResponsiveLayout();
   178      const isFocused = useIsFocused();
   179      const prevIsFocused = usePrevious(isFocused);
   180      const {isOffline} = useNetwork();
   181
   182      const {canUseSpotnanaTravel} = usePermissions();
   183      const canSendInvoice = useMemo(() => PolicyUtils.canSendInvoice(allPolicies as OnyxCollection<OnyxTypes.Policy>, session?.email), [allPolicies, session?.email]);
   184
   185      const quickActionAvatars = useMemo(() => {
   186          if (quickActionReport) {
   187              const avatars = ReportUtils.getIcons(quickActionReport, personalDetails);
   188              return avatars.length <= 1 || ReportUtils.isPolicyExpenseChat(quickActionReport) ? avatars : avatars.filter((avatar) => avatar.id !== session?.accountID);
   189          }
   190          return [];
   191          // Policy is needed as a dependency in order to update the shortcut details when the workspace changes
   192          // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
   193      }, [personalDetails, session?.accountID, quickActionReport, quickActionPolicy]);
   194
   195      const renderQuickActionTooltip = useCallback(
   196          () => (
   197              <Text>
   198                  <Text style={styles.quickActionTooltipTitle}>{translate('quickAction.tooltip.title')}</Text>
   199                  <Text style={styles.quickActionTooltipSubtitle}>{translate('quickAction.tooltip.subtitle')}</Text>
   200              </Text>
   201          ),
   202          [styles.quickActionTooltipTitle, styles.quickActionTooltipSubtitle, translate],
   203      );
   204
   205      const quickActionTitle = useMemo(() => {
   206          if (isEmptyObject(quickActionReport)) {
   207              return '';
   208          }
   209          if (quickAction?.action === CONST.QUICK_ACTIONS.SEND_MONEY && quickActionAvatars.length > 0) {
   210              const name: string = ReportUtils.getDisplayNameForParticipant(+(quickActionAvatars[0]?.id ?? -1), true) ?? '';
   211              return translate('quickAction.paySomeone', {name});
   212          }
   213          const titleKey = getQuickActionTitle(quickAction?.action ?? ('' as QuickActionName));
   214          return titleKey ? translate(titleKey) : '';
   215      }, [quickAction, translate, quickActionAvatars, quickActionReport]);
   216
   217      const hideQABSubtitle = useMemo(() => {
   218          if (isEmptyObject(quickActionReport)) {
   219              return true;
   220          }
   221          if (quickActionAvatars.length === 0) {
   222              return false;
   223          }
   224          const displayName = personalDetails?.[quickActionAvatars[0]?.id ?? -1]?.firstName ?? '';
   225          return quickAction?.action === CONST.QUICK_ACTIONS.SEND_MONEY && displayName.length === 0;
   226      }, [personalDetails, quickActionReport, quickAction?.action, quickActionAvatars]);
   227
   228      const navigateToQuickAction = () => {
   229          const selectOption = (onSelected: () => void, shouldRestrictAction: boolean) => {
   230              if (shouldRestrictAction && quickActionReport?.policyID && SubscriptionUtils.shouldRestrictUserBillableActions(quickActionReport.policyID)) {
   231                  Navigation.navigate(ROUTES.RESTRICTED_ACTION.getRoute(quickActionReport.policyID));
   232                  return;
   233              }
   234
   235              onSelected();
   236          };
   237
   238          const isValidReport = !(isEmptyObject(quickActionReport) || ReportUtils.isArchivedRoom(quickActionReport, reportNameValuePairs));
   239          const quickActionReportID = isValidReport ? quickActionReport?.reportID ?? '-1' : ReportUtils.generateReportID();
   240
   241          switch (quickAction?.action) {
   242              case CONST.QUICK_ACTIONS.REQUEST_MANUAL:
   243                  selectOption(() => IOU.startMoneyRequest(CONST.IOU.TYPE.SUBMIT, quickActionReportID, CONST.IOU.REQUEST_TYPE.MANUAL, true), true);
   244                  return;
   245              case CONST.QUICK_ACTIONS.REQUEST_SCAN:
   246                  selectOption(() => IOU.startMoneyRequest(CONST.IOU.TYPE.SUBMIT, quickActionReportID, CONST.IOU.REQUEST_TYPE.SCAN, true), true);
   247                  return;
   248              case CONST.QUICK_ACTIONS.REQUEST_DISTANCE:
   249                  selectOption(() => IOU.startMoneyRequest(CONST.IOU.TYPE.SUBMIT, quickActionReportID, CONST.IOU.REQUEST_TYPE.DISTANCE, true), true);
   250                  return;
   251              case CONST.QUICK_ACTIONS.SPLIT_MANUAL:
   252                  selectOption(() => IOU.startMoneyRequest(CONST.IOU.TYPE.SPLIT, quickActionReportID, CONST.IOU.REQUEST_TYPE.MANUAL, true), true);
   253                  return;
   254              case CONST.QUICK_ACTIONS.SPLIT_SCAN:
   255                  selectOption(() => IOU.startMoneyRequest(CONST.IOU.TYPE.SPLIT, quickActionReportID, CONST.IOU.REQUEST_TYPE.SCAN, true), true);
   256                  return;
   257              case CONST.QUICK_ACTIONS.SPLIT_DISTANCE:
   258                  selectOption(() => IOU.startMoneyRequest(CONST.IOU.TYPE.SPLIT, quickActionReportID, CONST.IOU.REQUEST_TYPE.DISTANCE, false), true);
   259                  return;
   260              case CONST.QUICK_ACTIONS.SEND_MONEY:
   261                  selectOption(() => IOU.startMoneyRequest(CONST.IOU.TYPE.PAY, quickActionReportID, CONST.IOU.REQUEST_TYPE.MANUAL, true), false);
   262                  return;
   263              case CONST.QUICK_ACTIONS.ASSIGN_TASK:
   264                  selectOption(() => Task.startOutCreateTaskQuickAction(isValidReport ? quickActionReportID : '', quickAction.targetAccountID ?? -1), false);
   265                  break;
   266              case CONST.QUICK_ACTIONS.TRACK_MANUAL:
   267                  selectOption(() => IOU.startMoneyRequest(CONST.IOU.TYPE.TRACK, quickActionReportID, CONST.IOU.REQUEST_TYPE.MANUAL, true), false);
   268                  break;
   269              case CONST.QUICK_ACTIONS.TRACK_SCAN:
   270                  selectOption(() => IOU.startMoneyRequest(CONST.IOU.TYPE.TRACK, quickActionReportID, CONST.IOU.REQUEST_TYPE.SCAN, true), false);
   271                  break;
   272              case CONST.QUICK_ACTIONS.TRACK_DISTANCE:
   273                  selectOption(() => IOU.startMoneyRequest(CONST.IOU.TYPE.TRACK, quickActionReportID, CONST.IOU.REQUEST_TYPE.DISTANCE, true), false);
   274                  break;
   275              default:
   276          }
   277      };
   278
   279      /**
   280       * Check if LHN status changed from active to inactive.
   281       * Used to close already opened FAB menu when open any other pages (i.e. Press Command + K on web).
   282       */
   283      const didScreenBecomeInactive = useCallback(
   284          (): boolean =>
   285              // When any other page is opened over LHN
   286              !isFocused && prevIsFocused,
   287          [isFocused, prevIsFocused],
   288      );
   289
   290      /**
   291       * Method called when we click the floating action button
   292       */
   293      const showCreateMenu = useCallback(
   294          () => {
   295              if (!isFocused && shouldUseNarrowLayout) {
   296                  return;
   297              }
   298              setIsCreateMenuActive(true);
   299              onShowCreateMenu?.();
   300          },
   301          // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
   302          [isFocused, shouldUseNarrowLayout],
   303      );
   304
   305      /**
   306       * Method called either when:
   307       * - Pressing the floating action button to open the CreateMenu modal
   308       * - Selecting an item on CreateMenu or closing it by clicking outside of the modal component
   309       */
   310      const hideCreateMenu = useCallback(
   311          () => {
   312              if (!isCreateMenuActive) {
   313                  return;
   314              }
   315              setIsCreateMenuActive(false);
   316              onHideCreateMenu?.();
   317          },
   318          // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
   319          [isCreateMenuActive],
   320      );
   321
   322      useEffect(() => {
   323          if (!didScreenBecomeInactive()) {
   324              return;
   325          }
   326
   327          // Hide menu manually when other pages are opened using shortcut key
   328          hideCreateMenu();
   329      }, [didScreenBecomeInactive, hideCreateMenu]);
   330
   331      useImperativeHandle(ref, () => ({
   332          hideCreateMenu() {
   333              hideCreateMenu();
   334          },
   335      }));
   336
   337      const toggleCreateMenu = () => {
   338          if (isCreateMenuActive) {
   339              hideCreateMenu();
   340          } else {
   341              showCreateMenu();
   342          }
   343      };
   344      // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
   345      const selfDMReportID = useMemo(() => ReportUtils.findSelfDMReportID(), [isLoading]);
   346
   347      return (
   348          <View style={styles.flexGrow1}>
   349              <PopoverMenu
   350                  onClose={hideCreateMenu}
   351                  isVisible={isCreateMenuActive && (!shouldUseNarrowLayout || isFocused)}
   352                  anchorPosition={styles.createMenuPositionSidebar(windowHeight)}
   353                  onItemSelected={hideCreateMenu}
   354                  fromSidebarMediumScreen={!shouldUseNarrowLayout}
   355                  menuItems={[
   356                      {
   357                          icon: Expensicons.ChatBubble,
   358                          text: translate('sidebarScreen.fabNewChat'),
   359                          onSelected: () => interceptAnonymousUser(Report.startNewChat),
   360                      },
   361                      ...(selfDMReportID
   362                          ? [
   363                                {
   364                                    icon: Expensicons.DocumentPlus,
   365                                    text: translate('iou.trackExpense'),
   366                                    onSelected: () => {
   367                                        interceptAnonymousUser(() =>
   368                                            IOU.startMoneyRequest(
   369                                                CONST.IOU.TYPE.TRACK,
   370                                                // When starting to create a track expense from the global FAB, we need to retrieve selfDM reportID.
   371                                                // If it doesn't exist, we generate a random optimistic reportID and use it for all of the routes in the creation flow.
   372                                                // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
   373                                                ReportUtils.findSelfDMReportID() || ReportUtils.generateReportID(),
   374                                            ),
   375                                        );
   376                                        if (!hasSeenTrackTraining && !isOffline) {
   377                                            setTimeout(() => {
   378                                                Navigation.navigate(ROUTES.TRACK_TRAINING_MODAL);
   379                                            }, CONST.ANIMATED_TRANSITION);
   380                                        }
   381                                    },
   382                                },
   383                            ]
   384                          : []),
   385                      {
   386                          icon: Expensicons.MoneyCircle,
   387                          text: translate('iou.submitExpense'),
   388                          onSelected: () =>
   389                              interceptAnonymousUser(() =>
   390                                  IOU.startMoneyRequest(
   391                                      CONST.IOU.TYPE.SUBMIT,
   392                                      // When starting to create an expense from the global FAB, there is not an existing report yet. A random optimistic reportID is generated and used
   393                                      // for all of the routes in the creation flow.
   394                                      ReportUtils.generateReportID(),
   395                                  ),
   396                              ),
   397                      },
   398                      {
   399                          icon: Expensicons.Transfer,
   400                          text: translate('iou.splitExpense'),
   401                          onSelected: () =>
   402                              interceptAnonymousUser(() =>
   403                                  IOU.startMoneyRequest(
   404                                      CONST.IOU.TYPE.SPLIT,
   405                                      // When starting to create a money request from the global FAB, there is not an existing report yet. A random optimistic reportID is generated and used
   406                                      // for all of the routes in the creation flow.
   407                                      ReportUtils.generateReportID(),
   408                                  ),
   409                              ),
   410                      },
   411                      {
   412                          icon: Expensicons.Send,
   413                          text: translate('iou.paySomeone', {}),
   414                          onSelected: () =>
   415                              interceptAnonymousUser(() =>
   416                                  IOU.startMoneyRequest(
   417                                      CONST.IOU.TYPE.PAY,
   418                                      // When starting to pay someone from the global FAB, there is not an existing report yet. A random optimistic reportID is generated and used
   419                                      // for all of the routes in the creation flow.
   420                                      ReportUtils.generateReportID(),
   421                                  ),
   422                              ),
   423                      },
   424                      {
   425                          icon: Expensicons.Task,
   426                          text: translate('newTaskPage.assignTask'),
   427                          onSelected: () => interceptAnonymousUser(() => Task.clearOutTaskInfoAndNavigate()),
   428                      },
   429                      ...(!isLoading && !Policy.hasActiveChatEnabledPolicies(allPolicies)
   430                          ? [
   431                                {
   432                                    displayInDefaultIconColor: true,
   433                                    contentFit: 'contain' as ImageContentFit,
   434                                    icon: Expensicons.NewWorkspace,
   435                                    iconWidth: 46,
   436                                    iconHeight: 40,
   437                                    text: translate('workspace.new.newWorkspace'),
   438                                    description: translate('workspace.new.getTheExpensifyCardAndMore'),
   439                                    onSelected: () => interceptAnonymousUser(() => App.createWorkspaceWithPolicyDraftAndNavigateToIt()),
   440                                },
   441                            ]
   442                          : []),
   443                      ...(quickAction?.action
   444                          ? [
   445                                {
   446                                    icon: getQuickActionIcon(quickAction?.action),
   447                                    text: quickActionTitle,
   448                                    label: translate('quickAction.header'),
   449                                    isLabelHoverable: false,
   450                                    floatRightAvatars: quickActionAvatars,
   451                                    floatRightAvatarSize: CONST.AVATAR_SIZE.SMALL,
   452                                    description: !hideQABSubtitle ? ReportUtils.getReportName(quickActionReport) ?? translate('quickAction.updateDestination') : '',
   453                                    numberOfLinesDescription: 1,
   454                                    onSelected: () => interceptAnonymousUser(() => navigateToQuickAction()),
   455                                    shouldShowSubscriptRightAvatar: ReportUtils.isPolicyExpenseChat(quickActionReport),
   456                                    shouldRenderTooltip: quickAction.isFirstQuickAction,
   457                                    tooltipAnchorAlignment: {
   458                                        vertical: CONST.MODAL.ANCHOR_ORIGIN_VERTICAL.BOTTOM,
   459                                        horizontal: CONST.MODAL.ANCHOR_ORIGIN_HORIZONTAL.LEFT,
   460                                    },
   461                                    tooltipShiftHorizontal: styles.popoverMenuItem.paddingHorizontal,
   462                                    tooltipShiftVertical: styles.popoverMenuItem.paddingVertical / 2,
   463                                    renderTooltipContent: renderQuickActionTooltip,
   464                                    tooltipWrapperStyle: styles.quickActionTooltipWrapper,
   465                                },
   466                            ]
   467                          : []),
   468                  ]}
   469                  withoutOverlay
   470                  anchorRef={fabRef}
   471              />
   472              <FloatingActionButton
   473                  accessibilityLabel={translate('sidebarScreen.fabNewChatExplained')}
   474                  role={CONST.ROLE.BUTTON}
   475                  isActive={isCreateMenuActive}
   476                  ref={fabRef}
   477                  onPress={toggleCreateMenu}
   478              />
   479          </View>
   480      );
   481  }
   482
   483  FloatingActionButtonAndPopover.displayName = 'FloatingActionButtonAndPopover';
   484
   485  export default withOnyx<FloatingActionButtonAndPopoverProps & RefAttributes<FloatingActionButtonAndPopoverRef>, FloatingActionButtonAndPopoverOnyxProps>({
   486      allPolicies: {
   487          key: ONYXKEYS.COLLECTION.POLICY,
   488          selector: policySelector,
   489      },
   490      isLoading: {
   491          key: ONYXKEYS.IS_LOADING_APP,
   492      },
   493      quickAction: {
   494          key: ONYXKEYS.NVP_QUICK_ACTION_GLOBAL_CREATE,
   495      },
   496      quickActionReport: {
   497          key: ({quickAction}) => `${ONYXKEYS.COLLECTION.REPORT}${quickAction?.chatReportID}`,
   498      },
   499      quickActionPolicy: {
   500          key: ({quickActionReport}) => `${ONYXKEYS.COLLECTION.POLICY}${quickActionReport?.policyID}`,
   501      },
   502      personalDetails: {
   503          key: ONYXKEYS.PERSONAL_DETAILS_LIST,
   504      },
   505      session: {
   506          key: ONYXKEYS.SESSION,
   507      },
   508      hasSeenTrackTraining: {
   509          key: ONYXKEYS.NVP_HAS_SEEN_TRACK_TRAINING,
   510      },
   511  })(forwardRef(FloatingActionButtonAndPopover));
   512
   513  export type {PolicySelector};

