    28  function getIconAndTitle(route: string, translate: LocaleContextProps['translate']): IconAndTitle {
    29      switch (route) {
    30          case CONST.DEBUG.DETAILS:
    31              return {icon: Expensicons.Info, title: translate('debug.details')};
    32          case CONST.DEBUG.JSON:
    33              return {icon: Expensicons.Eye, title: translate('debug.JSON')};
    34          case CONST.DEBUG.REPORT_ACTIONS:
    35              return {icon: Expensicons.Document, title: translate('debug.reportActions')};
    36          case CONST.DEBUG.REPORT_ACTION_PREVIEW:
    37              return {icon: Expensicons.Document, title: translate('debug.reportActionPreview')};
    38          case CONST.TAB_REQUEST.MANUAL:
    39              return {icon: Expensicons.Pencil, title: translate('tabSelector.manual')};
    40          case CONST.TAB_REQUEST.SCAN:
    41              return {icon: Expensicons.Receipt, title: translate('tabSelector.scan')};
    42          case CONST.TAB.NEW_CHAT:
    43              return {icon: Expensicons.User, title: translate('tabSelector.chat')};
    44          case CONST.TAB.NEW_ROOM:
    45              return {icon: Expensicons.Hashtag, title: translate('tabSelector.room')};
    46          case CONST.TAB_REQUEST.DISTANCE:
    47              return {icon: Expensicons.Car, title: translate('common.distance')};
    48          default:
    49              throw new Error(`Route ${route} has no icon nor title set.`);
    50      }
    51  }
    52
    53  function getOpacity(position: Animated.AnimatedInterpolation<number>, routesLength: number, tabIndex: number, active: boolean, affectedTabs: number[]) {
    54      const activeValue = active ? 1 : 0;
    55      const inactiveValue = active ? 0 : 1;
    56
    57      if (routesLength > 1) {
    58          const inputRange = Array.from({length: routesLength}, (v, i) => i);
    59
    60          return position.interpolate({
    61              inputRange,
    62              outputRange: inputRange.map((i) => (affectedTabs.includes(tabIndex) && i === tabIndex ? activeValue : inactiveValue)),
    63          });
    64      }
    65      return activeValue;
    66  }
